const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeOkeechobee = ee.FeatureCollection("USGS/WBD/2017/HUC08")
    .filter(ee.Filter.eq('name', 'Lake Okeechobee'));
  if (lakeOkeechobee.size().getInfo() === 0) {
    console.log("Could not find Lake Okeechobee geometry.");
    console.log("D");
    return;
  }
  const geometry = lakeOkeechobee.geometry();
  const dateStart = '2023-06-12';
  const dateEnd = '2023-06-13';

  // 2. Data Acquisition & Processing
  // Function to mask clouds using the Sentinel-2 SCL band and keep only water pixels.
  function maskS2cloudsAndWater(image) {
    const scl = image.select('SCL');
    // Keep only water pixels (class 6). This also implicitly masks clouds, land, etc.
    const waterMask = scl.eq(6);
    return image.updateMask(waterMask);
  }

  // Function to calculate NDCI (Normalized Difference Chlorophyll Index)
  // NDCI = (B5 - B4) / (B5 + B4)
  function addNDCI(image) {
    const ndci = image.normalizedDifference(['B5', 'B4']).rename('NDCI');
    return image.addBands(ndci);
  }

  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(dateStart, dateEnd);

  const collectionSize = s2Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-2 images found for June 12, 2023.");
    console.log("C1");
    return;
  }

  const mosaic = s2Collection.map(maskS2cloudsAndWater).map(addNDCI).mosaic();
  const ndciBand = mosaic.select('NDCI');

  // 3. Calculation
  // A threshold of NDCI > 0 is often used to indicate potential algal blooms.
  // We classify pixels into "bloom" (NDCI > 0) and "total water".
  const bloomPixels = ndciBand.gt(0); // Cyanobacteria/algae have positive NDCI

  const scale = 1000; // Use a coarse scale to avoid timeouts for large area stats.

  // Calculate the area of potential bloom
  const bloomAreaResult = bloomPixels.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  const bloomArea = ee.Number(bloomAreaResult.get('NDCI')).getInfo();

  // Calculate the total water area after cloud masking
  const totalWaterAreaResult = ndciBand.mask().multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  const totalWaterArea = ee.Number(totalWaterAreaResult.get('NDCI')).getInfo();

  // 4. Validation & Final Answer
  if (totalWaterArea === null || bloomArea === null) {
      console.log("Calculation failed: Bloom or Water area could not be computed.");
      console.log("C3");
      return;
  }

  if (totalWaterArea === 0) {
    console.log(`Image count: ${collectionSize}`);
    console.log("No valid water pixels found after cloud masking.");
    console.log("C2");
    return;
  }

  const bloomPercentage = (bloomArea / totalWaterArea) * 100;

  console.log(`Date: ${dateStart}`);
  console.log(`Image count: ${collectionSize}`);
  console.log(`Total clear water area (km2): ${(totalWaterArea / 1e6).toFixed(2)}`);
  console.log(`Cyanobacteria bloom area (km2): ${(bloomArea / 1e6).toFixed(2)}`);
  console.log(`Bloom Coverage (%): ${bloomPercentage.toFixed(2)}`);

  if (bloomPercentage > 30) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
